const NAME_START = /[A-Za-z_]/;
const NAME_PART = /[A-Za-z0-9_]/;
const DIGIT = /[0-9]/;
const OPERATORS = new Set(['+', '-', '*', '/', '%', '^']);

// Strict number literal, anchored to the start of the remaining input.
const NUMBER_RE = /^(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?/;
// Characters that, if immediately following a matched numeric literal, mean
// the literal did not consume everything it looked like it should.
const NUMBER_CONTINUATION = /[0-9A-Za-z.]/;

/**
 * Split an expression into tokens.
 *
 * @param {string} input expression source
 * @returns {{ type: 'number' | 'name' | 'operator' | 'lparen' | 'rparen' | 'comma', value: number | string, index: number }[]}
 *   tokens in source order
 */
export function tokenize(input) {
  const tokens = [];
  let i = 0;
  const n = input.length;

  while (i < n) {
    const c = input[i];

    if (/\s/.test(c)) {
      i += 1;
      continue;
    }

    const looksNumeric = DIGIT.test(c) || (c === '.' && DIGIT.test(input[i + 1] || ''));
    if (looksNumeric) {
      const start = i;
      const rest = input.slice(i);
      const match = NUMBER_RE.exec(rest);
      const matchedLength = match ? match[0].length : 0;
      const end = i + matchedLength;
      const nextChar = input[end];
      if (matchedLength === 0 || (nextChar !== undefined && NUMBER_CONTINUATION.test(nextChar))) {
        throw new ExprError(`malformed number at ${start}`, start);
      }
      tokens.push({ type: 'number', value: Number(match[0]), index: start });
      i = end;
      continue;
    }

    if (NAME_START.test(c)) {
      const start = i;
      let end = i + 1;
      while (end < n && NAME_PART.test(input[end])) end += 1;
      tokens.push({ type: 'name', value: input.slice(start, end), index: start });
      i = end;
      continue;
    }

    if (OPERATORS.has(c)) {
      tokens.push({ type: 'operator', value: c, index: i });
      i += 1;
      continue;
    }

    if (c === '(') {
      tokens.push({ type: 'lparen', value: c, index: i });
      i += 1;
      continue;
    }

    if (c === ')') {
      tokens.push({ type: 'rparen', value: c, index: i });
      i += 1;
      continue;
    }

    if (c === ',') {
      tokens.push({ type: 'comma', value: c, index: i });
      i += 1;
      continue;
    }

    const codePoint = input.codePointAt(i);
    const grapheme = String.fromCodePoint(codePoint);
    throw new ExprError(`unexpected character '${grapheme}' at ${i}`, i);
  }

  return tokens;
}
"}

