import { ExprError, tokenize } from './tokenize.js';
import { parse } from './parse.js';

export { ExprError, tokenize, parse };

const CONSTANTS = { pi: Math.PI, e: Math.E };

function roundHalfUp(x) {
  // Ties toward positive infinity, unlike Math.round's mostly-equivalent
  // behaviour except for negative halves (Math.round(-2.5) === -2 already,
  // which matches "toward positive infinity").
  return Math.floor(x + 0.5);
}

const FUNCTIONS = {
  abs: { arity: 1, fn: (a) => Math.abs(a) },
  sqrt: { arity: 1, fn: (a) => Math.sqrt(a) },
  floor: { arity: 1, fn: (a) => Math.floor(a) },
  ceil: { arity: 1, fn: (a) => Math.ceil(a) },
  round: { arity: 1, fn: (a) => roundHalfUp(a) },
  sign: { arity: 1, fn: (a) => Math.sign(a) },
  pow: { arity: 2, fn: (a, b) => Math.pow(a, b) },
  atan2: { arity: 2, fn: (a, b) => Math.atan2(a, b) },
  min: { arity: -1, fn: (...args) => Math.min(...args) },
  max: { arity: -1, fn: (...args) => Math.max(...args) },
};

function checkFinite(value, index) {
  if (!Number.isFinite(value)) throw new ExprError(`non-finite result at ${index}`, index);
  return value;
}

function evalNode(node, env) {
  switch (node.type) {
    case 'number':
      return node.value;

    case 'variable': {
      if (Object.prototype.hasOwnProperty.call(env, node.name)) {
        const value = env[node.name];
        if (typeof value !== 'number' || !Number.isFinite(value)) {
          throw new ExprError(`variable ${node.name} is not a finite number at ${node.index}`, node.index);
        }
        return value;
      }
      if (Object.prototype.hasOwnProperty.call(CONSTANTS, node.name)) {
        return CONSTANTS[node.name];
      }
      throw new ExprError(`unknown variable: ${node.name} at ${node.index}`, node.index);
    }

    case 'unary': {
      const operand = evalNode(node.operand, env);
      const value = node.op === '-' ? -operand : +operand;
      return checkFinite(value, node.index);
    }

    case 'binary': {
      const left = evalNode(node.left, env);
      const right = evalNode(node.right, env);
      let value;
      switch (node.op) {
        case '+':
          value = left + right;
          break;
        case '-':
          value = left - right;
          break;
        case '*':
          value = left * right;
          break;
        case '/':
          if (right === 0) throw new ExprError(`division by zero at ${node.index}`, node.index);
          value = left / right;
          break;
        case '%':
          if (right === 0) throw new ExprError(`division by zero at ${node.index}`, node.index);
          value = left % right;
          break;
        case '^':
          value = Math.pow(left, right);
